'use strict';
const $ = id => document.getElementById(id);
const equations = Array.from({length:25}, (_,i) => ({a:Math.floor(i/5)+1,b:i%5+1}));
const chinese = ['零','一','二','三','四','五','六','七','八','九','十'];
const english = ['zero','one','two','three','four','five','six','seven','eight','nine','ten'];
function language(){return $('language').value==='en'?'en':'zh';}
function spokenEquation(){const {a,b}=equations[index];return language()==='en'?`${english[a]} plus ${english[b]} equals ${english[a+b]}.`:`${chinese[a]}加${chinese[b]}等于${chinese[a+b]}。`;}
let index=0, playing=false, generation=0, timer=null, utterance=null, installPrompt=null;
const synth=window.speechSynthesis;
const cells=[];
for(let a=1;a<=5;a++){for(let b=1;b<=5;b++){const i=(a-1)*5+b-1;const button=document.createElement('button');button.className='cell';button.textContent=`${a}+${b}`;button.setAttribute('aria-label',`${a} 加 ${b}`);button.addEventListener('click',()=>select(i));cells.push(button);$('addition-table').append(button);}}
function render(){const {a,b}=equations[index];cells.forEach((c,i)=>{c.classList.toggle('active',i===index);c.setAttribute('aria-pressed',String(i===index));});$('equation').innerHTML=`<span class="number-a">${a}</span><span class="operator">+</span><span class="number-b">${b}</span><span class="operator">=</span><span class="answer">${a+b}</span>`;$('spoken-equation').textContent=spokenEquation();$('progress-text').textContent=`${index+1} / 25`;$('progress-fill').style.width=`${(index+1)*4}%`;setRepeat(0);}
function setRepeat(n){$('repeat-one').className='repeat-pill'+(n===1?' current':n===2?' done':'');$('repeat-two').className='repeat-pill'+(n===2?' current':'');}
function controls(){ $('play-label').textContent=playing?'暂停':'开始';$('play-icon').textContent=playing?'Ⅱ':'▶';$('play').setAttribute('aria-label',playing?'暂停':'开始'); }
function cancel(){generation++;clearTimeout(timer);timer=null;if(synth)synth.cancel();utterance=null;}
function pause(){playing=false;cancel();controls();$('reading-status').textContent='休息一下，随时继续';setRepeat(0);}
function delay(ms,token,fn){timer=setTimeout(()=>{if(playing&&token===generation)fn();},ms);}
function availableVoices(){if(!synth)return [];const prefix=language();const female=/\b(Yaoyao|Huihui|Xiaoxiao|Xiaoyi|Xiaomo|Xiaoyou|Xiaoshuang|Xiaozhen|Tingting|Meijia|Zira|Aria|Jenny|Michelle|Ana|Samantha|Karen|Moira|Tessa|Ava|Emma|Susan|Victoria)\b|female|女声/i;const male=/\b(Kangkang|Yunxi|Yunjian|Yunyang|David|Mark|Guy|Ryan|George|Daniel|James|Eric|Andrew|Brian)\b|\bmale\b|男声/i;const score=v=>(female.test(v.name)?1000:0)+(/natural|neural|online|premium|enhanced/i.test(v.name)?100:0)+(/\b(Yaoyao|Xiaoshuang|Ana|Zira)\b/i.test(v.name)?20:0)+(v.lang.toLowerCase()===(prefix==='en'?'en-us':'zh-cn')?10:0);return synth.getVoices().filter(v=>v.lang.toLowerCase().replace('_','-').startsWith(prefix+'-')&&!male.test(v.name)).sort((a,b)=>score(b)-score(a));}
function refreshVoices(){const select=$('voice');const previous=select.value;select.replaceChildren();const automatic=document.createElement('option');automatic.value='auto';automatic.textContent='自动选择';select.append(automatic);availableVoices().forEach(v=>{const option=document.createElement('option');option.value=v.voiceURI||v.name;option.textContent=v.name;select.append(option);});select.value=availableVoices().some(v=>(v.voiceURI||v.name)===previous)?previous:'auto';}
function voice(){const voices=availableVoices();return voices.find(v=>(v.voiceURI||v.name)===$('voice').value)||voices[0]||null;}
function readRound(round,token){if(!playing||token!==generation)return;setRepeat(round);$('reading-status').textContent=`正在读 · 第 ${round} 遍`;if(!synth||!window.SpeechSynthesisUtterance){pause();$('audio-message').hidden=false;$('audio-message').textContent='此浏览器不支持朗读，请使用 Chrome、Edge 或 Safari。';return;}
 utterance=new SpeechSynthesisUtterance(spokenEquation());utterance.lang=language()==='en'?'en-US':'zh-CN';const selectedVoice=voice();if(selectedVoice){utterance.voice=selectedVoice;utterance.lang=selectedVoice.lang;}utterance.rate=$('speed').value==='slow'?0.9:$('speed').value==='fast'?1.3:1.12;utterance.pitch=1;utterance.volume=1;
 $('spoken-equation').textContent=spokenEquation();$('audio-message').textContent=selectedVoice?'':`设备尚未提供${language()==='en'?'英语':'中文'}语音。如没有声音，请添加相应语言的设备语音。`;$('audio-message').hidden=!!selectedVoice;
 let finished=false;const done=()=>{if(finished||token!==generation||!playing)return;finished=true;clearTimeout(timer);if(round===1){delay($('speed').value==='slow'?750:450,token,()=>readRound(2,token));}else{$('reading-status').textContent='你也来读一读！';delay($('speed').value==='slow'?1600:1000,token,()=>{index=(index+1)%25;render();readRound(1,token);});}};
 utterance.onend=done;utterance.onerror=event=>{if(token!==generation||!playing)return;if(event.error==='canceled'||event.error==='interrupted')return;pause();$('audio-message').hidden=false;$('audio-message').textContent='朗读暂时无法播放。请检查所选语言的语音和设备声音，再点击开始。';};
 synth.speak(utterance);timer=setTimeout(()=>{if(token===generation&&playing&&!finished){pause();$('audio-message').hidden=false;$('audio-message').textContent='朗读没有响应。请检查设备语音，再点击开始。';}},20000);
}
function start(){cancel();$('audio-message').hidden=true;playing=true;controls();readRound(1,generation);}
function select(i){cancel();index=(i+25)%25;render();if(playing)readRound(1,generation);else $('reading-status').textContent='点击开始，听一听';}
$('play').addEventListener('click',()=>playing?pause():start());$('previous').addEventListener('click',()=>select(index-1));$('next').addEventListener('click',()=>select(index+1));$('replay').addEventListener('click',start);$('speed').addEventListener('change',()=>{if(playing)start();});
$('language').addEventListener('change',()=>{refreshVoices();$('spoken-equation').textContent=spokenEquation();if(playing)start();});$('voice').addEventListener('change',()=>{if(playing)start();});if(synth?.addEventListener)synth.addEventListener('voiceschanged',refreshVoices);refreshVoices();
document.addEventListener('visibilitychange',()=>{if(document.hidden&&playing)pause();});window.addEventListener('pagehide',pause);
window.addEventListener('beforeinstallprompt',event=>{event.preventDefault();installPrompt=event;$('install').hidden=false;});$('install').addEventListener('click',async()=>{if(!installPrompt)return;await installPrompt.prompt();await installPrompt.userChoice;installPrompt=null;$('install').hidden=true;});window.addEventListener('appinstalled',()=>{$('install').hidden=true;$('connection-status').textContent='已安装，随时学习';});
if('serviceWorker' in navigator)window.addEventListener('load',()=>{navigator.serviceWorker.register('./sw.js').then(()=>{$('connection-status').textContent='离线也能看加法表';}).catch(()=>{$('connection-status').textContent='在线学习';});});
const context=document.modelContext;if(context?.registerTool){try{Promise.resolve(context.registerTool({name:'select_addition_equation',description:'Select an equation with both operands between 1 and 5. If the lesson is playing, restart its two readings.',inputSchema:{type:'object',properties:{a:{type:'integer',minimum:1,maximum:5},b:{type:'integer',minimum:1,maximum:5}},required:['a','b'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute(input){if(!input||!Number.isInteger(input.a)||!Number.isInteger(input.b)||input.a<1||input.a>5||input.b<1||input.b>5)throw new Error('Operands must be integers between 1 and 5');select((input.a-1)*5+input.b-1);return {...equations[index],answer:input.a+input.b,playing};}})).catch(()=>{});}catch{}}
render();controls();
